draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // stick figures
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W/4 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W/4 + 30, H/2 + 70);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 20);
  ctx.lineTo(W - W/4, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 50);
  ctx.lineTo(W - W/4 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 50);
  ctx.lineTo(W - W/4 + 30, H/2 + 70);
  ctx.stroke();

  // holding hands
  ctx.beginPath();
  ctx.moveTo(W/4 + 30, H/2 + 70);
  ctx.lineTo(W - W/4 - 30 + Math.sin(t) * 20, H/2 + 70);
  ctx.stroke();

  // faces
  ctx.beginPath();
  ctx.arc(W/4, H/2 - 10, 5, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W - W/4, H/2 - 10, 5, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
